window.PAIRS=[{"n":5,"s":0.851,"o":{"i":"관세사2018_35-03-1","t":"세관장은 관세의 납세의무자가 아닌 자가 관세의 납부를 보증한 경우 그 담보로 관세에 충당하고 남은 금액이 있을 때에는 그 보증인에게 이를 직접 돌려주어야 한다.","y":2018,"e":"관세사 1차"},"x":{"i":"관세사2026_43-07-3","t":"세관장은 관세의 납세의무자가 아닌 자가 관세의 납부를 보증한 경우 그 담보로 관세에 충당하고 남은 금액이 있을 때에는 납세의무자에게 이를 직접 돌려주어야 한다.","y":2026,"e":"관세사 1차"}},{"n":5,"s":0.807,"o":{"i":"관세사2017_34-19-2","t":"납세의무자는 납세신고한 세액을 납부하기 전에 그 세액이 과부족(過不足)하다는 것을 알게 되었을 때에는 납세신고한 세액을 정정할 수 있다.","y":2017,"e":"관세사 1차"},"x":{"i":"관세사2018_35-08-1","t":"납세의무자는 납세신고한 세액을 납부하기 전에 그 세액이 과부족(過不足)하다는 것을 알게 되었을 때에도 납세신고한 세액을 정정할 수 없다.","y":2018,"e":"관세사 1차"}},{"n":5,"s":0.757,"o":{"i":"관세사2018_35-03-4","t":"세관장은 담보를 제공한 납세의무자가 그 납부기한까지 해당 관세를 납부하지 아니하면 재정경제부령으로 정하는 바에 따라 그 담보를 해당 관세에 충당할 수 있다.","y":2018,"e":"관세사 1차"},"x":{"i":"관세사2019_36-07-2","t":"관세청장은 담보를 제공한 납세의무자가 그 납부기한까지 해당 관세를 납부하지 아니하면 대통령령으로 정하는 바에 따라 그 담보를 해당 관세에 충당할 수 있다.","y":2019,"e":"관세사 1차"}},{"n":5,"s":0.728,"o":{"i":"관세사2018_35-03-5","t":"납세의무자(관세의 납부를 보증한 자를 포함)는 관세법에 따라 계속하여 담보를 제공하여야 하는 사유가 있는 경우에는 관세청장이 정하는 바에 따라 일정 기간에 제공하여야 하는 담보를 포괄하여 미리 세관장에게 제공할 수 있다.","y":2018,"e":"관세사 1차"},"x":{"i":"관세사2026_43-07-2","t":"관세의 납부를 보증한 자는 관세법에 따라 계속하여 담보를 제공하여야 하는 사유가 있는 경우 관세청장이 정하는 바에 따라 일정 기간에 제공하여야 하는 담보를 포괄하여 미리 세관장에게 제공할 수 없다.","y":2026,"e":"관세사 1차"}},{"n":7,"s":0.574,"o":{"i":"관세사2018_35-24-3","t":"통관역은 국외와 연결되고 국경에 근접한 철도역 중에서 관세청장이 지정한다.","y":2018,"e":"관세사 1차"},"x":{"i":"관세사2024_41-20-2","t":"통관역은 국외와 연결되고 국경에 근접한 철도역 중에서 세관장이 지정하고, 통관장은 관세통로에 접속한 장소 중에서 관세청장이 지정한다.","y":2024,"e":"관세사 1차"}},{"n":7,"s":0.574,"o":{"i":"관세사2025_42-31-2","t":"항구의 경우 국제항으로 지정되기 위해서는 국제무역선인 5천톤급 이상의 선박이 연간 50회 이상 입항하거나 입항할 것으로 예상되어야 한다.","y":2025,"e":"관세사 1차"},"x":{"i":"관세사2024_41-20-4","t":"국제무역선인 5천톤급 이상의 선박이 연간 40회 이상 입항하거나 입항할 것으로 예상되어야 국제항으로 지정될 수 있다.","y":2024,"e":"관세사 1차"}},{"n":6,"s":0.629,"o":{"i":"관세사2026_43-19-5","t":"심사청구는 해당 처분을 한 것을 안 날부터 90일 이내에 제기하여야 한다.","y":2026,"e":"관세사 1차"},"x":{"i":"관세사2024_41-16-5","t":"심사청구는 해당 처분이 내려진 날부터 90일 이내에 제기하여야 한다.","y":2024,"e":"관세사 1차"}},{"n":6,"s":0.593,"o":{"i":"관세사2018_35-21-1","t":"세관공무원은 특정한 분야만을 조사할 필요가 있는 등 대통령령으로 정하는 경우를 제외하고는 신고납부세액과 관세법 및 다른 법령에서 정하는 수출입 관련 의무 이행과 관련하여 그 권한에 속하는 사항을 통합하여 조사하는 것을 원칙으로 한다.","y":2018,"e":"관세사 1차"},"x":{"i":"관세사2026_43-19-3","t":"세관공무원은 조세채권의 확보 등을 위하여 긴급히 조사할 필요가 있는 경우에 신고납부세액과 관세법 및 다른 법령에서 정하는 수출입 관련 의무 이행과 관련하여 그 권한에 속하는 사항을 통합하여 조사하는 것을 원칙으로 한다.","y":2026,"e":"관세사 1차"}},{"n":6,"s":0.485,"o":{"i":"관세사2023_40-12-1","t":"심사청구인은 관세사를 대리인으로 선임할 수 있다.","y":2023,"e":"관세사 1차"},"x":{"i":"관세사2026_43-18-1","t":"심판청구인은 관세사를 대리인으로 선임할 수 있지만, 변호사를 대리인으로 선임할 수는 없다.","y":2026,"e":"관세사 1차"}},{"n":6,"s":0.448,"o":{"i":"관세사2019_36-31-4","t":"심사청구의 대리인은 본인을 위하여 청구에 관한 모든 행위를 할 수 있다. 다만, 청구의 취하는 특별한 위임을 받은 경우에만 할 수 있다.","y":2019,"e":"관세사 1차"},"x":{"i":"관세사2026_43-18-4","t":"대리인은 본인을 위하여 청구에 관한 모든 행위를 할 수 있으며, 청구의 취하 또한 특별한 위임을 받지 않아도 가능하다.","y":2026,"e":"관세사 1차"}},{"n":9,"s":0.556,"o":{"i":"관세사2026_43-28-5","t":"우편물에 대한 관세의 납세의무는 해당 우편물이 반송되면 소멸한다.","y":2026,"e":"관세사 1차"},"x":{"i":"관세사2022_39-28-5","t":"우편물에 대한 관세의 납세의무는 해당 우편물이 반송되어도 소멸하지 않는다.","y":2022,"e":"관세사 1차"}},{"n":9,"s":0.512,"o":{"i":"관세사2022_39-02-4","t":"수출물품ㆍ반송물품 가격결정에 관한 자료는 해당 신고에 대한 수리일부터 3년이다.","y":2022,"e":"관세사 1차"},"x":{"i":"관세사2022_39-02-1","t":"보세화물반출입에 관한 자료는 해당 신고에 대한 수리일부터 3년이다.","y":2022,"e":"관세사 1차"}},{"n":9,"s":0.489,"o":{"i":"관세사2017_34-11-1","t":"수입하려는 물품을 수입신고 전에 운송수단, 관세통로, 하역통로 또는 관세법에 따른 장치 장소로부터 즉시 반출하려는 자는 대통령령으로 정하는 바에 따라 세관장에게 즉시반출신고를 하여야 한다.","y":2017,"e":"관세사 1차"},"x":{"i":"관세사2019_36-36-2","t":"수입하려는 물품을 수입신고 전에 운송수단, 관세통로, 하역통로 또는 관세법에 따른 장치 장소로 즉시 반입하려는 자는 세관장의 승인을 받아야 한다.","y":2019,"e":"관세사 1차"}},{"n":9,"s":0.486,"o":{"i":"관세사2018_35-28-2","t":"관세청장은 관세의 부과와 징수, 과세 불복에 대한 심리 및 형사소추를 위하여 수출입신고자료 등 대통령령으로 정하는 사항을 대한민국 정부가 다른 국가와 관세행정에 관한 협력 및 상호지원에 관하여 체결한 협정과 국제기구와 체결한 국제협약에 따라 다른 법률에 저촉되지 아니하는 범위에서 다른 국가와 교환할 수 있다.","y":2018,"e":"관세사 1차"},"x":{"i":"관세사2019_36-34-2","t":"관세청장은 관세의 부과와 징수를 위하여 수출입신고자료 등 재정경제부령으로 정하는 사항을 대한민국 정부가 다른 국가와 관세행정에 관한 협력 및 상호지원에 관하여 체결한 협정에 따라 다른 법률에 저촉되지 아니하는 범위에서 다른 국가와 교환하여야 하며, 상호주의 원칙에 따라 상대국에 수출입신고자료 등을 제공하는 것을 제한하여서는 아니 된다.","y":2019,"e":"관세사 1차"}},{"n":1,"s":0.774,"o":{"i":"관세사2026_43-01-5","t":"“환적”이란 동일한 세관의 관할구역에서 입국 또는 입항하는 운송수단에서 출국 또는 출항하는 운송수단으로 물품을 옮겨 싣는 것을 말한다.","y":2026,"e":"관세사 1차"},"x":{"i":"관세사2018_35-01-3","t":"“복합환적”(複合換積)이란 동일한 세관의 관할구역에서 입국 또는 입항하는 운송 수단에서 출국 또는 출항하는 운송수단으로 물품을 옮겨 싣는 것을 말한다.","y":2018,"e":"관세사 1차"}},{"n":1,"s":0.771,"o":{"i":"관세사2026_43-01-1","t":"“반송”이란 국내에 도착한 외국물품이 수입통관절차를 거치지 아니하고 다시 외국으로 반출되는 것을 말한다.","y":2026,"e":"관세사 1차"},"x":{"i":"관세사2017_34-12-2","t":"“반송”이란 국내에 도착한 외국물품이 수입통관절차를 거쳐 다시 외국으로 반출되는 것을 말한다.","y":2017,"e":"관세사 1차"}},{"n":1,"s":0.442,"o":{"i":"관세사2026_43-01-2","t":"“국제무역선”이란 무역을 위하여 우리나라와 외국 간을 운항하는 선박을 말한다.","y":2026,"e":"관세사 1차"},"x":{"i":"관세사2017_34-12-1","t":"“외국무역선”이란 무역을 위하여 외국에서만 운항하는 선박을 말한다.","y":2017,"e":"관세사 1차"}},{"n":2,"s":0.652,"o":{"i":"관세사2020_37-04-1","t":"세관장은 납세의무자가 서면으로 요청하면 과세가격을 결정하는 데에 사용한 방법과 과세가격 및 그 산출근거를 그 납세의무자에게 서면으로 통보하여야 한다.","y":2020,"e":"관세사 1차"},"x":{"i":"관세사2017_34-16-2","t":"세관장은 납세의무자의 요청이 없더라도 과세가격을 결정하는 데에 사용한 방법과 과세가격 및 그 산출근거를 납세의무자에게 서면으로 통보하여야 한다.","y":2017,"e":"관세사 1차"}},{"n":4,"s":0.756,"o":{"i":"관세사2024_41-07-2","t":"세관장은 관세환급금의 과다환급액을 징수할 때에는 과다환급을 한 날의 다음 날부터 징수결정을 하는 날까지의 기간에 대하여 대통령령으로 정하는 이율에 따라 계산한 금액을 과다환급액에 더하여야 한다.","y":2024,"e":"관세사 1차"},"x":{"i":"관세사2019_36-03-5","t":"세관장은 관세환급금의 과다환급액을 징수할 때에는 과다환급을 한 날부터 징수결정을 하는 날까지의 기간에 대하여 한국은행이 정하는 이율에 따라 계산한 금액을 과다 환급액에 더하여야 한다.","y":2019,"e":"관세사 1차"}},{"n":4,"s":0.724,"o":{"i":"관세사2022_39-17-1","t":"수입신고가 수리된 개인의 자가사용물품이 수입한 상태 그대로 수입신고 수리일부터 6개월 이내에 보세구역에 반입하였다가 다시 수출하는 경우에는 수입할 때 납부한 관세를 환급한다.","y":2022,"e":"관세사 1차"},"x":{"i":"관세사2017_34-32-1","t":"수입신고가 수리된 개인의 자가사용물품이 수입한 상태 그대로 수출되는 경우로서 수입 신고일부터 1년 이내에 보세구역에 반입하였다가 다시 수출하는 경우에는 수입할 때 납부한 관세를 환급한다.","y":2017,"e":"관세사 1차"}},{"n":4,"s":0.711,"o":{"i":"관세사2019_36-13-4","t":"관세의 분할납부를 승인받은 자가 파산선고를 받은 경우에는 그 파산관재인이 관세를 납부하여야 한다.","y":2019,"e":"관세사 1차"},"x":{"i":"관세사2022_39-17-3","t":"분할납부를 승인받은 자가 파산선고를 받은 경우에는 그 청산인이 관세를 납부하여야한다.","y":2022,"e":"관세사 1차"}},{"n":4,"s":0.662,"o":{"i":"관세사2023_40-01-1","t":"세관장은 납세의무자가 환급세액의 환급을 청구할 때에는 대통령령으로 정하는 바에 따라 지체 없이 이를 관세환급금으로 결정하고 30일 이내에 환급하여야 한다.","y":2023,"e":"관세사 1차"},"x":{"i":"관세사2019_36-03-4","t":"세관장은 납세의무자가 환급세액의 환급을 청구할 때에는 재정경제부령에 따라 지체 없이 이를 관세환급금으로 결정하고 60일 이내에 환급하여야 한다.","y":2019,"e":"관세사 1차"}},{"n":11,"s":0.793,"o":{"i":"관세사2025_42-38-4","t":"수입신고의 수리 전까지 협정관세의 적용신청을 하지 못한 수입자는 해당 물품의 수입신고 수리일부터 1년 이내에 협정관세의 적용을 신청할 수 있다.","y":2025,"e":"관세사 1차"},"x":{"i":"관세사2020_37-38-3","t":"수입신고의 수리 전까지 협정관세의 적용신청을 하지 못한 수입자는 해당 물품의 수입 신고일부터 2년 이내에 협정관세의 적용을 신청할 수 있다.","y":2020,"e":"관세사 1차"}},{"n":11,"s":0.667,"o":{"i":"관세사2019_36-37-4","t":"협정관세란 협정에 따라 체약상대국을 원산지로 하는 수입물품에 대하여 관세를 철폐하거나 세율을 연차적으로 인하하여 부과하여야 할 관세를 말한다.","y":2019,"e":"관세사 1차"},"x":{"i":"관세사2020_37-36-1","t":"\"협정관세\"란 자유무역협정에 따라 체약상대국을 원산지로 하는 수입물품에 대하여 관세를 철폐하거나 세율을 일시적으로 인상 또는 인하하여 부과하여야 할 관세를 말한다.","y":2020,"e":"관세사 1차"}},{"n":11,"s":0.559,"o":{"i":"관세사2020_37-36-2","t":"\"체약상대국\"이란 우리나라와 자유무역협정을 체결한 국가(국가연합ㆍ경제공동체 또는 독립된 관세영역을 포함한다)를 말한다.","y":2020,"e":"관세사 1차"},"x":{"i":"관세사2019_36-37-2","t":"체약상대국이란 우리나라와 자유무역협정을 체결한 국가를 말하며 국가연합ㆍ경제공동체 또는 독립된 관세영역은 제외한다.","y":2019,"e":"관세사 1차"}},{"n":11,"s":0.542,"o":{"i":"관세사2018_35-36-3","t":"해당 물품이 둘 이상의 국가에 걸쳐 생산ㆍ가공 또는 제조된 경우, 해당 물품에 대하여 일정 수준 이상의 부가가치를 창출한 국가를 그 물품의 원산지로 한다.","y":2018,"e":"관세사 1차"},"x":{"i":"관세사2018_35-36-2","t":"해당 물품이 둘 이상의 국가에 걸쳐 생산ㆍ가공 또는 제조된 경우, 해당 물품의 생산ㆍ가공 또는 제조의 공정을 수행한 모든 국가를 그 물품의 원산지로 한다.","y":2018,"e":"관세사 1차"}},{"n":10,"s":0.831,"o":{"i":"관세사2025_42-26-1","t":"관세청장은 관세법 제241조제1항 및 제2항을 위반하여 수입하는 「마약류 관리에 관한 법률」에 따른 마약류의 위치정보를 수집할 수 있다.","y":2025,"e":"관세사 1차"},"x":{"i":"관세사2025_42-26-3","t":"관세청장은 관세법 제241조제1항 및 제2항을 위반하여 수입하는 「마약류 관리에 관한 법률」에 따라 지정된 임시마약류의 위치정보를 수집할 수 있다.","y":2025,"e":"관세사 1차"}},{"n":10,"s":0.652,"o":{"i":"관세사2017_34-30-1","t":"관세범에 관한 조사ㆍ처분은 세관공무원이 한다.","y":2017,"e":"관세사 1차"},"x":{"i":"관세사2020_37-23-1","t":"관세범에 관한 조사ㆍ처분은 검찰공무원이 한다.","y":2020,"e":"관세사 1차"}},{"n":10,"s":0.467,"o":{"i":"관세사2017_34-30-3","t":"사법경찰관리의 직무를 행하는 세관공무원이 법령에 의하여 피의자를 구속하는 때에는 세관관서ㆍ국가경찰관서 또는 교도관서에 유치하여야 한다.","y":2017,"e":"관세사 1차"},"x":{"i":"관세사2025_42-21-5","t":"사법경찰관리의 직무를 행하는 세관공무원이 법령에 의하여 피의자를 구속하는 때에는 시ㆍ군ㆍ읍ㆍ면사무소에 유치할 수 있다.","y":2025,"e":"관세사 1차"}},{"n":3,"s":0.768,"o":{"i":"관세사2017_34-34-4","t":"조약에 따라 우리나라가 양허한 품목에 대하여 그 양허를 철회한 경우에는 해당 조약에 따라 철회의 효력이 발생한 날부터 관세법에 따른 세율을 적용한다.","y":2017,"e":"관세사 1차"},"x":{"i":"관세사2020_37-19-5","t":"조약에 따라 우리나라가 양허한 품목에 대하여 그 양허를 철회한 경우에는 해당 조약에 따라 철회의 효력이 발생한 날의 다음날부터「관세법」에 따른 세율을 적용한다.","y":2020,"e":"관세사 1차"}},{"n":3,"s":0.761,"o":{"i":"관세사2020_37-19-4","t":"일반특혜관세를 부과할 때 해당 특혜대상물품의 수입이 국내산업에 미치는 영향 등을 고려하여 그 물품에 적용되는 세율에 차등을 둘 수 있다.","y":2020,"e":"관세사 1차"},"x":{"i":"관세사2019_36-12-2","t":"일반특혜관세를 부과할 때 해당 특혜대상물품의 수입이 국내산업에 미치는 영향 등을 고려하여 그 물품에 적용되는 세율에 차등을 둘 수 있으나 특혜대상물품의 수입수량 등을 한정할 수 없다.","y":2019,"e":"관세사 1차"}},{"n":3,"s":0.648,"o":{"i":"관세사2017_34-36-3","t":"관세청장은 회의의 원활한 운영을 위하여 품목분류와 관련된 기술적인 사항 등에 대한 의견을 듣기 위하여 관련 학계ㆍ연구기관 또는 협회 등에서 활동하는 자를 기술자문위원으로 위촉할 수 있다.","y":2017,"e":"관세사 1차"},"x":{"i":"관세사2020_37-16-4","t":"위원회의 위원장은 회의의 원활한 운영을 위하여 품목분류와 관련된 기술적인 사항 등에 대한 의견을 듣기 위하여 관련 학계에서 활동하는 자를 기술자문위원으로 위촉한다.","y":2020,"e":"관세사 1차"}},{"n":3,"s":0.59,"o":{"i":"관세사2020_37-16-1","t":"위원회의 위원장은 관세청의 3급 공무원 또는 고위공무원단에 속하는 일반직공무원으로서 관세청장이 지정하는 자가 된다.","y":2020,"e":"관세사 1차"},"x":{"i":"관세사2017_34-36-2","t":"관세품목분류위원회의 위원장은 관세청 차장 또는 고위공무원단에 속하는 특수직 공무원으로서 관세청장이 지정하는 자가 된다.","y":2017,"e":"관세사 1차"}}];
